## Simulation study: when does a DeepSurv survival sub-model help BJM?
##
## Data are generated by the backward joint model's own factorization, so the
## longitudinal sub-model is correctly specified and only the survival
## sub-model varies:
##   X       : 5 signal covariates (x4 binary) + p_noise N(0, 1) noise covariates
##   T | X   : Weibull PH, H(t | x) = lambda t^1.5 exp{g(x)}, sd(g) scaled to 1
##   Y | T   : Y_ij = 1 + 0.1 s_ij + alpha * 0.5 (s_ij - T) + b0_i + b1_i s_ij + e_ij
##             (linear in visit time s, T and their product: BJM's model class),
##             yearly visits (jittered) before min(T, C)
##   C       : Uniform(2, 15)
## alpha sets how much the biomarker says about T (0.2 weak, 1 strong).

suppressPackageStartupMessages({
  library(BJM)
  library(BJMdeep)
})

g_raw <- function(x, scenario) {
  switch(scenario,
    linear = 0.5 * x$x1 - 0.5 * x$x2 + 0.4 * x$x3 + 0.5 * x$x4 - 0.3 * x$x5,
    nonlinear = , highdim = 0.7 * (x$x1^2 - 1) + 0.7 * x$x2 * x$x3 + 0.8 * sin(2 * x$x5) +
      0.6 * x$x4 * x$x1)
}

## sd(g) = 1 in every scenario, so they differ in shape, not in signal size
g_scale <- local({
  cache <- list()
  function(scenario) {
    if (is.null(cache[[scenario]])) {
      x <- draw_x(2e5, 0)
      cache[[scenario]] <<- 1 / stats::sd(g_raw(x, scenario))
    }
    cache[[scenario]]
  }
})

draw_x <- function(n, p_noise) {
  x <- data.frame(x1 = rnorm(n), x2 = rnorm(n), x3 = rnorm(n), x4 = rbinom(n, 1, 0.5), x5 = rnorm(n))
  for (j in seq_len(p_noise)) x[[paste0("z", j)]] <- rnorm(n)
  x
}

simulate_cohort <- function(n, scenario, alpha, id_offset = 0) {
  p_noise <- if (scenario == "highdim") 15 else 0
  x <- draw_x(n, p_noise)
  g <- g_raw(x, scenario) * g_scale(scenario)
  lambda <- log(2) / 6^1.5                          # median 6 years at g = 0
  etime_true <- (-log(runif(n)) / (lambda * exp(g)))^(1 / 1.5)
  cens <- runif(n, 2, 15)
  base <- cbind(id = id_offset + seq_len(n), x, g_true = g,
                etime = pmin(etime_true, cens), status = as.integer(etime_true <= cens))
  b0 <- rnorm(n, 0, 0.5)
  b1 <- rnorm(n, 0, 0.1)
  rows <- lapply(seq_len(n), function(i) {
    visits <- c(0, seq_len(30) + runif(30, -0.2, 0.2))
    visits <- visits[visits < base$etime[i]]
    T_i <- etime_true[i]
    y <- 1 + 0.1 * visits + alpha * 0.5 * (visits - T_i) + b0[i] + b1[i] * visits +
      rnorm(length(visits), 0, 0.3)
    data.frame(id = base$id[i], visit = visits, Y = y)
  })
  long <- merge(do.call(rbind, rows), base, by = "id")
  long <- long[order(long$id, long$visit), ]
  long$Tlog <- log(long$etime + 1)                  # the (unused) transform BJM asks for
  long
}

trans <- list(survival_variable_all = list("Tlog"),
              survival_trans_function = list(function(x) log(x + 1)))

one_replicate <- function(rep, n_train, scenario, alpha, n_test = 1000,
                          landmarks = c(1, 3, 5), horizon = 2, ds_control = NULL) {
  set.seed(1e5 + rep)
  train <- simulate_cohort(n_train, scenario, alpha)
  test <- simulate_cohort(n_test, scenario, alpha, id_offset = 1e6)
  train_base <- train[!duplicated(train$id), ]
  test_base <- test[!duplicated(test$id), ]
  xs <- setdiff(names(train_base), c("id", "visit", "Y", "g_true", "etime", "status", "Tlog"))

  long_fit <- longitudinalSub(list(train[train$status == 1, ]),
                              list("Y" = Y ~ visit + etime + etime:visit),
                              list("Y" = ~ visit | id))
  if (is.null(ds_control)) {
    ds_control <- deepsurvControl(hidden = c(32, 16), activation = "elu", weight_decay = 1e-3,
                                  learning_rate = 1e-3, epochs = 3000, valid_fraction = 0.2,
                                  patience = 150, n_ensemble = 5, seed = rep)
  }
  f_lin <- reformulate(xs, response = quote(Surv(etime, status)))
  fits <- list(
    cox = function() survivalSub(train_base, f_lin, NULL),
    deepsurv = function() survivalSubDeep(train_base, f_lin, NULL, control = ds_control),
    oracle = function() survivalSub(train_base, Surv(etime, status) ~ g_true, NULL)
  )
  out <- list()
  for (m in names(fits)) {
    t0 <- Sys.time()
    fit <- fits[[m]]()
    secs <- as.numeric(difftime(Sys.time(), t0, units = "secs"))
    test_m <- if (m == "deepsurv") addDeepScore(test, fit) else test
    tb <- test_m[!duplicated(test_m$id), ]
    lp <- predict(fit$coxph_fit, newdata = tb, type = "lp", reference = "zero")
    cidx <- survival::concordance(Surv(etime, status) ~ lp, data = tb, reverse = TRUE)$concordance
    p <- suppressWarnings(performancePlot(test_m, long_fit, fit, prediction_time = landmarks,
                                          horizon = horizon, time_variable = "visit",
                                          trans$survival_variable_all, trans$survival_trans_function,
                                          bandcount1 = 10, bandcount2 = 20))$data
    out[[m]] <- rbind(
      data.frame(model = m, measure = "C-index (survival sub-model)", landmark = NA, value = cidx),
      data.frame(model = m, measure = p$measure, landmark = p$landmark, value = p$value))
    out[[m]]$fit_seconds <- secs
  }
  res <- do.call(rbind, out)
  cbind(rep = rep, n_train = n_train, scenario = scenario, alpha = alpha,
        censored = mean(train_base$status == 0), res)
}
